import org.eclipse.jface.preference.StringFieldEditor;
import org.eclipse.jface.preference.FieldEditorPreferencePage;
import org.eclipse.swt.widgets.Composite;

class NegativeTestPage extends FieldEditorPreferencePage {
    protected void createFieldEditors() {
        Composite parent = getFieldEditorParent();
        String key = "anotherKey";
        String label = "Another Label";
        int lines = 1;

        // Different width, should not match
        StringFieldEditor field1 = new StringFieldEditor(key, label, 100, lines, StringFieldEditor.VALIDATE_ON_FOCUS_LOST, parent);
        addField(field1);

        // Different constructor arguments count or type, should not match
        StringFieldEditor field2 = new StringFieldEditor(key + "2", label + "2", 20, StringFieldEditor.VALIDATE_ON_FOCUS_LOST, parent); // Assuming a 4-arg constructor for example
        addField(field2);
    }
}
